import{_ as a,c as e,o as t,af as s}from"./chunks/framework.BKeRpnBD.js";const f=JSON.parse('{"title":"46、【升】 巽下坤上","description":"子夏易传 - 46、【升】 巽下坤上","frontmatter":{"title":"46、【升】 巽下坤上","description":"子夏易传 - 46、【升】 巽下坤上"},"headers":[],"relativePath":"zh/classics/zixia/048.md","filePath":"zh/classics/zixia/048.md"}'),i={name:"zh/classics/zixia/048.md"};function r(_,p,c,o,n,l){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="_46、【升】-巽下坤上" tabindex="-1">46、【升】 巽下坤上 <a class="header-anchor" href="#_46、【升】-巽下坤上" aria-label="Permalink to “46、【升】 巽下坤上”">​</a></h1><p>卦辞：升，元亨，用見大人，勿恤，南征吉。</p><p>彖曰：柔以時升，巽而順剛，中而應，是以大亨用見大人。勿恤，有慶也。南征吉，志行也。</p><p>子夏：柔，卑道也。巽，木道也。其道升而大也。見可而升得，其時也。内體巽而外順於物，剛中而上應之，是以亨也。合大人之徳，用見之，而勿恤有慶者也。南征吉，出諸幽而升於明也。志獲於此矣。</p><p>象曰：地中生木，升君子以順徳，積小以高大。</p><p>子夏：木生浸而大也。剛中而柔順也。君子欲其升也。立本以愼徳，巽於卑順於上，則能積小而至於大也。</p><p>初六，允升大吉。</p><p>象曰：允升大吉，上合志也。</p><p>子夏：巽者剛。巽柔，柔順剛也。上承於剛，誠信相與，升而合徳，其升矣，故大吉。</p><p>九二，孚，乃利用禴，无咎。</p><p>象曰：九二之孚，有喜也。</p><p>子夏：剛而能正，中而无私，應上以升之象，豈假豐物而後享焉。上應其誠，下升而大，雖非其位得其道也。故有喜而无咎也。</p><p>九三，升虚邑。</p><p>象曰：升虚邑，无所疑也。</p><p>子夏：上體順也。應而升之，虚邑以待也，升何疑哉。</p><p>六四，王用亨于岐山，吉。无咎。</p><p>象曰：王用亨于岐山，順事也。</p><p>子夏：位輔乎尊，而不待諸升者，通上下，安險阻之任，難之地也。而順以當位，恭以事上，得其吉矣，亦又何咎。</p><p>六五，貞吉升階。</p><p>象曰：貞吉升階，大得志也。</p><p>子夏：以柔道而至於中也。升階而就其位，正之吉也。可謂大志也。</p><p>上六，冥升，利于不息之貞。</p><p>象曰：冥升，在上消不富也。</p><p>子夏：上而不已，昧於升也。時消也。安所息乎，利以守正，不求孳孳也。</p>',24)])])}const h=a(i,[["render",r]]);export{f as __pageData,h as default};
